//! Random input never panics and always finishes (REQ-5788, until the fuzz target of TODO-5760
//! exists). Run in a debug build, so any arithmetic overflow panics, this checks the bounds the
//! geometry's `arithmetic_side_effects` allowances rely on.
#![allow(
    clippy::arithmetic_side_effects,
    clippy::unwrap_used,
    clippy::indexing_slicing,
    reason = "a test: a fixed generator, and failure is a panic"
)]

use naplps::{Canvas, StrokeFont, Terminal};

/// Pages generated by the quick test (every push) and by the long one (the full gate).
const QUICK_PAGES: usize = 200;
/// See [`QUICK_PAGES`]: the long run took about 400 seconds in a debug build on 12 November 2026.
const LONG_PAGES: usize = 3000;
/// Bytes per page at most.
const MAX_LENGTH: u64 = 1500;
/// The generator's fixed seed, so every run tests the same pages.
const SEED: u64 = 0x005E_ED0F_1983;

/// xorshift64*: a fixed, dependency-free generator.
struct Generator(u64);

impl Generator {
    fn next(&mut self) -> u64 {
        self.0 ^= self.0 >> 12;
        self.0 ^= self.0 << 25;
        self.0 ^= self.0 >> 27;
        self.0.wrapping_mul(0x2545_F491_4F6C_DD1D)
    }

    /// A byte biased toward what NAPLPS reads: controls, PDI opcodes, operand bytes, C1 and GR.
    fn byte(&mut self) -> u8 {
        let value = self.next();
        let byte = value.to_le_bytes()[1];
        match value % 8 {
            0 => byte & 0x1F,                                         // C0
            1 => 0x20 | (byte & 0x1F),                                // PDI opcodes, space and punctuation
            2 | 3 => 0x40 | (byte & 0x3F),                            // operand bytes
            4 => 0x80 | (byte & 0x1F),                                // C1
            5 => [0x0E, 0x0F, 0x19, 0x1D, 0x1B][(byte % 5) as usize], // shifts and ESC
            _ => byte,
        }
    }
}

#[test]
fn random_pages_never_panic_and_always_finish() {
    render_random_pages(QUICK_PAGES);
}

#[test]
#[ignore = "long: 3000 random pages, about seven minutes in a debug build; run by the full gate"]
fn many_random_pages_never_panic_and_always_finish() {
    render_random_pages(LONG_PAGES);
}

fn render_random_pages(pages: usize) {
    let font =
        StrokeFont::parse("[primary]\n41 0 6 0,2,3,9 3,9,6,2 1,5,5,5\n[supplementary]\n41 0 6 0,9,6,9\n").unwrap();
    let mut generator = Generator(SEED);
    let mut canvas = Canvas::new(320, 240).unwrap();
    for _ in 0..pages {
        let length = generator.next() % MAX_LENGTH;
        let page: Vec<u8> = (0..length).map(|_| generator.byte()).collect();
        let mut terminal = Terminal::new(4);
        terminal.set_font(font.clone());
        // In pieces, as a serial line delivers it.
        for piece in page.chunks(37) {
            let _ = terminal.feed(&mut canvas, piece);
        }
        let _ = terminal.finish(&mut canvas);
    }
}
